#include<bits/stdc++.h>
using namespace std;constexpr int N=3968,K=45;
int main(){vector<vector<int>>adj(N);vector<bitset<N>>bits(N);ifstream f("research/mixed_tier17_eval_subgroup_20261105/cache/graph_edges.bin",ios::binary);int u,v;while(f.read((char*)&u,4)&&f.read((char*)&v,4)){adj[u].push_back(v);adj[v].push_back(u);bits[u][v]=bits[v][u]=1;}vector<int>seed;ifstream z("research/mixed_tier17_eval_subgroup_20261105/cache/baseline_seed.bin",ios::binary);while(z.read((char*)&u,4))seed.push_back(u);assert(seed.size()==44);mt19937 rng(170105);int best=999;auto start=chrono::steady_clock::now();for(int run=0;run<1000;run++){vector<char>on(N);vector<int>deg(N),tabuAdd(N),tabuDel(N);vector<int>sel=seed;for(int x:sel){on[x]=1;for(int y:adj[x])deg[y]++;}int md=999;vector<int>opt;for(int i=0;i<N;i++)if(!on[i]){if(deg[i]<md){md=deg[i];opt.clear();}if(deg[i]==md)opt.push_back(i);}int x=opt[rng()%opt.size()];on[x]=1;sel.push_back(x);for(int y:adj[x])deg[y]++;int cost=md;
for(int it=1;it<=300000;it++){int delta0=999,cu=-1,cv=-1,ties=0;vector<int>candidates;for(int t=0;t<600;t++){int v=rng()%N;if(!on[v])candidates.push_back(v);}if(it%50==0){int md=999;for(int v=0;v<N;v++)if(!on[v])md=min(md,deg[v]);for(int v=0;v<N;v++)if(!on[v]&&deg[v]<=md+1)candidates.push_back(v);}for(int u:sel)for(int v:candidates){int delta=deg[v]-(int)bits[u][v]-deg[u];if((tabuAdd[v]>it||tabuDel[u]>it)&&cost+delta>=best)continue;if(delta<delta0){delta0=delta;ties=0;}if(delta==delta0 && rng()%(++ties)==0){cu=u;cv=v;}}if(cu<0)break;for(int y:adj[cu])deg[y]--;on[cu]=0;for(int y:adj[cv])deg[y]++;on[cv]=1;*find(sel.begin(),sel.end(),cu)=cv;cost+=delta0;tabuAdd[cu]=it+7+rng()%18+cost*2;tabuDel[cv]=it+7+rng()%18+cost*2;if(cost<best){best=cost;cerr<<"best conflicts "<<best<<" run "<<run<<" iter "<<it<<" time "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"\n";if(!best){ofstream out("research/mixed_tier17_eval_subgroup_20261105/cache/potential.txt");for(int z:sel)out<<z<<" ";out<<"\n";cerr<<"POTENTIAL 45 orbits, cross-cap verification required\n";return 0;}}} }
}
